import React, { useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import Navbar from './components/Navbar'; 

import Footer from './components/Footer';
import Home from './pages/Home';
import About from './pages/About';
import Services from './pages/Services'; 
import Investor from './pages/InvestorRelation'; 
import Gallery from './pages/Gallery'; 
import Branches from './pages/Branches';
import Contact from './components/Contact';
import Career from './components/Career';
import SupportTeam from './pages/SupportTeam';

// This helper component handles the scrolling logic
function ScrollToHandler() {
  const { pathname, hash } = useLocation();

  useEffect(() => {
    // If there is no hash (e.g. #bod-section), scroll to top
    if (!hash) {
      window.scrollTo(0, 0);
    } else {
      // If there is a hash, wait for page/tabs to render, then scroll
      setTimeout(() => {
        const id = hash.replace('#', '');
        const element = document.getElementById(id);
        if (element) {
          element.scrollIntoView({ behavior: 'smooth' });
        }
      }, 150); 
    }
  }, [pathname, hash]);

  return null;
}

function App() {
  return (
    <Router>
      <div className="App">
        {/* Monitors every navigation change */}
        <ScrollToHandler />
        
        <Navbar />
        
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/about" element={<About />} />
          <Route path="/services" element={<Services />} />
          <Route path="/investor-relations" element={<Investor />} />
          <Route path="/gallery" element={<Gallery />} />
          <Route path="/branches" element={<Branches />} />
          <Route path="/contact" element={<Contact />} />
          <Route path="/career" element={<Career />} />
          <Route path="/support" element={<SupportTeam />} />
        </Routes>

        <Footer />
      </div>
    </Router>
  );
}

export default App;
